// Generated by ebigentserver/behavior: fixtures are real recorded
// situations (rule:predicate-tests-generated-from-episodes), pinned to
// their episode and tick so a failure names a replayable moment.
package gen

import (
	"encoding/json"
	"testing"

	"github.com/shibukawa/ebigentserver/samples/tictactoe/ttt"
)

func TestCompiledPolicyReproducesRecordedDecisions(t *testing.T) {
	cases := []struct {
		name string
		obs  string
		want string
	}{
		{name: "ttt-000_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-009_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,2,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_2"},
		{name: "ttt-016_tick4_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,1,0,0,0,0,2,2,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":1908874353,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_2"},
		{name: "ttt-025_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-034_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-041_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,0,0,0,0,2,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-050_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-058_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,0,0,0,0,2,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-068_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-075_tick4_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,1,0,2,0,0,0,0,2],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":1908874353,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_2"},
		{name: "ttt-084_tick4_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,1,0,0,0,2,2,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":1908874353,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_2"},
		{name: "ttt-094_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,0,0,2,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-103_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,0,2,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-112_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,2,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-120_tick4_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,1,0,2,0,2,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":1908874353,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_2"},
		{name: "ttt-130_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,2,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-138_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-146_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,0,0,2,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-154_tick4_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,1,0,0,2,2,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":1908874353,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_2"},
		{name: "ttt-163_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-171_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-178_tick2_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,0,2,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":954437176,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_1"},
		{name: "ttt-186_tick0_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[0,0,0,0,0,0,0,0,0],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":0,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_0"},
		{name: "ttt-193_tick8_slot1", obs: "{\"You\":1,\"Mark\":1,\"Board\":[1,2,1,1,2,1,2,0,2],\"NextTurn\":1,\"Signal\":{\"score\":0,\"progress\":3817748707,\"evaluation\":0,\"reward_delta\":0,\"terminal\":\"not_terminal\"}}", want: "play_7"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			var obs ttt.Sight
			if err := json.Unmarshal([]byte(c.obs), &obs); err != nil {
				t.Fatal(err)
			}
			got, ok := Decide(obs)
			if !ok {
				t.Fatalf("no decision for a recorded decision point")
			}
			if name := actionName(got); name != c.want {
				t.Fatalf("decided %s, recorded %s", name, c.want)
			}
		})
	}
}
